  window.AriseKnowledge = {
    scan: scan,
    relatedTo: relatedTo,
    open: open,
    close: close,
    refresh: refresh,
    storageKey: UI_KEY
  };

  if (document.body) boot();
  else document.addEventListener("DOMContentLoaded", boot);
